const normalizeCity = (city: string): string =>
  String(city || '')
    .toLowerCase()
    .replace(/[ñ]/g, 'n')
    .replace(/[^a-z0-9 ]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

