export const postalCodeForCity = (city: string): string => {
  const norm = normalizeCity(city);
  if (!norm) return '';
  if (POSTAL_ALIASES[norm]) return POSTAL_ALIASES[norm];
  const key = Object.keys(BULACAN_POSTAL_CODES).find(
    (c) => normalizeCity(c) === norm
  );
  return key ? BULACAN_POSTAL_CODES[key] : '';
};
